fn is_min_heap(a: &Vec<i32>) -> bool {
    let n = a.len();
    
    // Iterate through all parent nodes (indices 0 to n/2 - 1)
    for i in 0..n / 2 {
        let left_child = 2 * i + 1;
        let right_child = 2 * i + 2;
        
        // Check left child if it exists
        if left_child < n && a[left_child] < a[i] {
            return false;
        }
        
        // Check right child if it exists
        if right_child < n && a[right_child] < a[i] {
            return false;
        }
    }
    
    true
}